-- Completa políticas por empresa para as tabelas genéricas criadas na migration inicial.
create or replace function punho_membro_ativo() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from punho_membros where user_id=auth.uid() and ativo) $$;
do $$ declare t text; begin foreach t in array array['punho_leads','punho_colaboradores','punho_maquinas','punho_veiculos','punho_recebimentos','punho_documentos','punho_campanhas','punho_instalacoes'] loop execute format('drop policy if exists empresa_membros on %I',t); execute format('create policy empresa_membros on %I for all using (empresa_id=punho_empresa_atual() and punho_membro_ativo()) with check (empresa_id=punho_empresa_atual() and punho_membro_ativo())',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['punho_eventos_auditoria','punho_despesas','punho_subscricoes'] loop execute format('drop policy if exists empresa_gestor on %I',t); execute format('create policy empresa_gestor on %I for all using (empresa_id=punho_empresa_atual() and punho_e_gestor()) with check (empresa_id=punho_empresa_atual() and punho_e_gestor())',t); end loop; end $$;
